/// A request to the `sysinfo` interface that passed the receiver's schema check.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Request {
    Tasks { start: u32 },
    Cpus,
    Memory,
    Physmap,
    Vmap { pid: u64 },
    Caps { pid: u64 },
    Endpoints { start: u32 },
    Irqs,
    Devices,
    History { slow: bool, count: u16, start: u16 },
    Load,
    Holders { index: u32 },
    Authority { start: u32 },
}

/// Checks a received message against the schema (MC-2.4): method, major version, unused bits, capability kind, and
/// for buffer calls every length and value of a private copy of the request (MC-2.11). `cap` is the slot passed to
/// `recv`; an unexpected capability is dropped (MC-2.12). The `Call` is what the reply functions need.
pub fn decode(request: &Received, cap: usize) -> core::result::Result<(Request, Call), Reject> {
    let words = request.data;
    wire::header(request, cap, MAJOR)?;
    match words[0] & 0xFF {
        1 => {
            let mut copy = [0u8; 4];
            let (call, length) = wire::take_buffer(request, cap, 7482, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let start = <u32 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Tasks { start }, call))
        }
        2 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 426, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Cpus, call))
        }
        3 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 136, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Memory, call))
        }
        4 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 6146, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Physmap, call))
        }
        5 => {
            let mut copy = [0u8; 8];
            let (call, length) = wire::take_buffer(request, cap, 1922, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let pid = <u64 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Vmap { pid }, call))
        }
        6 => {
            let mut copy = [0u8; 8];
            let (call, length) = wire::take_buffer(request, cap, 3074, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let pid = <u64 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Caps { pid }, call))
        }
        7 => {
            let mut copy = [0u8; 4];
            let (call, length) = wire::take_buffer(request, cap, 8194, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let start = <u32 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Endpoints { start }, call))
        }
        8 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 466, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Irqs, call))
        }
        9 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 4610, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Devices, call))
        }
        10 => {
            let mut copy = [0u8; 5];
            let (call, length) = wire::take_buffer(request, cap, 6602, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let slow = <bool as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            let count = <u16 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            let start = <u16 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::History { slow, count, start }, call))
        }
        11 => {
            let mut copy = [0u8; 1];
            let (call, length) = wire::take_buffer(request, cap, 36, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Load, call))
        }
        12 => {
            let mut copy = [0u8; 4];
            let (call, length) = wire::take_buffer(request, cap, 1282, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let index = <u32 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Holders { index }, call))
        }
        13 => {
            let mut copy = [0u8; 4];
            let (call, length) = wire::take_buffer(request, cap, 7170, &mut copy)?;
            let mut r = Reader::new(&copy[..length]);
            let start = <u32 as Wire>::decode(&mut r).ok_or(Reject::Invalid)?;
            if !r.done() { return Err(Reject::Invalid); }
            Ok((Request::Authority { start }, call))
        }
        _ => { wire::discard(request, cap); Err(Reject::Invalid) }
    }
}

pub fn reply_tasks(call: Call, value: core::result::Result<&[Task], Error>) -> Result<()> {
    let value = match value { Ok(value) => value, Err(error) => return wire::reply_code(call, error as usize) };
    wire::reply_buffer(call, |w| codec::encode_slice::<Task, 40>(value, w))
}
